// Initialization (Static or Dynamic)
pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int resource_ready = 0;

// Dynamic setup alternative:
// pthread_mutex_init(&mtx, NULL);
// pthread_cond_init(&cond, NULL);

// Cleanup:
// pthread_mutex_destroy(&mtx);
// pthread_cond_destroy(&cond);

// ---

// Waiting Thread (Consumer) Logic
pthread_mutex_lock(&mtx);

// Wait loop protects against spurious wakeups
while (resource_ready == 0) {
    // Atomically releases lock and blocks.
    // Reacquires lock upon wakeup.
    pthread_cond_wait(&cond, &mtx);
}

// Critical section processing:
resource_ready = 0;
// Use resource...

pthread_mutex_unlock(&mtx);

// ---

// Signaling Thread (Producer) Logic
pthread_mutex_lock(&mtx);

// Set the condition
// data production...
resource_ready = 1;

// Wake up one waiting thread
pthread_cond_signal(&cond);

// Use pthread_cond_broadcast(&cond)
// to wake up all waiting threads

pthread_mutex_unlock(&mtx);
